INSERT INTO changelog (title, body, created_at) VALUES ('Автовихід через 30 хвилин', 'На сторінці входу зʼявилась галочка «Запамʼятати цей пристрій на 30 днів». На своєму телефоні й компʼютері постав її один раз. Без галочки (чужий компʼютер) система сама виходить після 30 хвилин без дій: екран переходить на вхід, дані не лишаються відкритими. Також сесія закривається разом із браузером. Поки ти працюєш, вона продовжується сама. Ті, хто зараз уже увійшов, лишаються в системі до старого строку.', datetime('now'));
